'use strict';
const APP=document.getElementById('app'),TOAST=document.getElementById('toast');
const state={auth:null,hotels:[],hotel:null,slug:'',tab:'dashboard',guest:null,token:'',preview:false,lang:'he',guestTab:'home',catalog:{},staff:[],selectedThread:0,cart:{},assets:[],modal:null,prompt:null,alertsEnabled:false,lastAlertStats:null,lastEventIds:null,lastGuestReplyId:null,receptionSeen:null,lastAlertSuccess:0,lastAlertFailure:0,roomQuery:'',roomFilter:'',pendingRoomFocus:false};
const PERMS={guests:['🪪','Reception & QR'],requests:['🛎','Guest Requests'],orders:['🍽','Food Orders'],folio:['💳','Room Folio'],chat:['💬','Guest Messages'],rooms:['🛏','Rooms & Types'],menu:['☕','Menu Catalog'],activities:['🌴','Activities'],amenities:['🧺','Room Amenities'],services:['✨','Hotel Services'],branding:['🎨','Hotel Branding'],media:['📷','Media Library']};
const CATALOG={room_types:'Room Types',rooms:'Physical Rooms',menu:'Menu Products',activities:'Activities',amenities:'Room Amenities',services:'Hotel Services'};
const LABEL={name_en:'English name',name_he:'Hebrew name',description_en:'English description',description_he:'Hebrew description',size:'Room size',max_guests:'Max guests',image:'Photo',active:'Visible to guests',room:'Room number',room_type_id:'Room type',floor:'Floor',notes:'Internal notes',category:'Category',price_cents:'Price',starts:'Starts',ends:'Ends',location:'Location',capacity:'Capacity',basis:'Quota basis',period:'Quota period',quota:'Quota per person / room'};
const FIELDS={room_types:['name_en','name_he','description_en','description_he','size','max_guests','image','active'],rooms:['room','room_type_id','floor','notes','image','active'],menu:['name_en','name_he','description_en','description_he','category','price_cents','image','active'],activities:['name_en','name_he','description_en','description_he','starts','ends','location','capacity','price_cents','image','active'],amenities:['name_en','name_he','basis','period','quota','image','active'],services:['name_en','name_he','description_en','description_he','category','image','active']};
const PRESET=['resort-hero.webp','resort-pool.webp','room-garden.webp','room-ocean.webp','room-villa.webp','dining.webp','wellness-spa.webp','yoga.webp','coconut.webp','smoothie.webp','tea.webp','sandwich.webp','fruit.webp','curry.webp','fries.webp','brownie.webp'];
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function pathImg(v){if(!v)return '/static/assets/photo-placeholder.svg';if(String(v).startsWith('/media/'))return v;return '/static/assets/'+encodeURIComponent(String(v));}
function img(v,cl='',style=''){return `<img class="${cl}" src="${esc(pathImg(v))}" style="${esc(style)}" loading="lazy" alt="Hotel photograph">`;}
function fmt(cents,cur){try{return new Intl.NumberFormat('en-US',{style:'currency',currency:cur||'USD'}).format(Number(cents||0)/100);}catch{return `${(Number(cents||0)/100).toFixed(2)} ${cur||''}`;}}
function dateFmt(d){if(!d)return '—';try{return new Date(d).toLocaleString(state.lang==='he'?'he-IL':'en-GB',{dateStyle:'medium',timeStyle:'short'});}catch{return d;}}
function getLocalDate(n=0){let d=new Date(Date.now()+n*86400000);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function toLocal(d){if(!d)return '';let a=new Date(d);return `${a.getFullYear()}-${String(a.getMonth()+1).padStart(2,'0')}-${String(a.getDate()).padStart(2,'0')}T${String(a.getHours()).padStart(2,'0')}:${String(a.getMinutes()).padStart(2,'0')}`;}
function notify(s,error=false){let d=document.createElement('div');d.className='toast'+(error?' error':'');d.textContent=s;TOAST.append(d);setTimeout(()=>d.remove(),4200);}
async function api(url,method='GET',body,raw=false){const opts={method,credentials:'same-origin',headers:{}};if(body!==undefined){if(raw){opts.body=body;opts.headers['Content-Type']=body.type||'application/octet-stream';}else{opts.body=JSON.stringify(body);opts.headers['Content-Type']='application/json';}}let resp;try{resp=await fetch(url,opts);}catch{throw new Error('Network error — check the server connection.');}let data;if(resp.headers.get('Content-Type')?.includes('application/json'))data=await resp.json();else data=await resp.text();if(!resp.ok)throw Error(data.error||`Request failed: ${resp.status}`);return data;}
function modal(html){state.modal=html;renderModal();}function closeModal(){state.modal=null;renderModal();}function renderModal(){let m=document.getElementById('modalroot');if(!m){m=document.createElement('div');m.id='modalroot';document.body.append(m);}m.innerHTML=state.modal?`<div class="modalwrap" data-close="1"><div class="modal" role="dialog" aria-modal="true">${state.modal}</div></div>`:'';}
function hroute(s,part){return `/api/h/${encodeURIComponent(s)}/${part}`;}
function hotelApi(part,method='GET',body,raw=false){return api(hroute(state.slug,'manage/'+part),method,body,raw);}
function available(p){const u=state.auth?.user;return !!(u&&(['owner','manager'].includes(u.role)||u.permissions?.some(x=>[p,'view:'+p,'edit:'+p].includes(x))));}
function canEdit(p){const u=state.auth?.user;return !!(u&&(['owner','manager'].includes(u.role)||u.permissions?.some(x=>[p,'edit:'+p].includes(x))));}
function navTo(tab){state.tab=tab;state.selectedThread=0;window.history.replaceState({},'',location.pathname+'#'+tab);renderManager();}
function renderError(err){notify(err.message||String(err),true);}
function brand(){return `<div class="brand"><span class="brandmark">✧</span><span class="brandtext">STAYOS</span></div>`;}
function pageIntro(eyebrow,title,desc){return `<div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div>`;}
function rowActions(items){return `<div class="actions">${items.join('')}</div>`;}
function btn(label,act,cls=''){return `<button class="btn ${cls}" data-action="${act}">${label}</button>`;}
function empty(title='Nothing here yet',desc='Add your first item to start configuring this hotel.') {return `<div class="blank"><div class="ico">✦</div><strong>${title}</strong><p style="margin-top:10px">${desc}</p></div>`;}
function isOwner(){return state.auth?.user?.role==='owner';}
async function init(){try{state.auth=await api('/api/auth/me');const p=location.pathname;
 if(p.startsWith('/h/')){let m=p.match(/^\/h\/([a-z0-9-]+)(?:\/(guest|preview))?$/);if(!m){APP.innerHTML='Invalid hotel link';return;}state.slug=m[1];state.preview=m[2]!=='guest';state.token=new URLSearchParams(location.search).get('token')||sessionStorage.getItem('stayos_guest_'+state.slug)||'';await loadPublic();if(m[2]==='guest'&&state.token){sessionStorage.setItem('stayos_guest_'+state.slug,state.token);try{state.guest=await api(hroute(state.slug,'guest/'+encodeURIComponent(state.token)+'/session'));state.preview=false;}catch(e){state.guest=null;state.preview=true;notify(e.message,true);}}renderGuest();return;}
 if(!state.auth.authenticated){renderLogin();return;}
 if(isOwner()){await loadHotels();renderOwner();return;}
 state.slug=(await findMyHotel());if(!state.slug){APP.innerHTML=empty('Hotel account not assigned');return;}await loadHotelManagement();state.tab=location.hash.slice(1)||'dashboard';renderManager();
 }catch(e){APP.innerHTML=`<div class="panel" style="margin:35px">Unable to load STAYOS: ${esc(e.message)}<br><br><a class="btn" href="/">Retry</a></div>`;}}
async function findMyHotel(){const h=await api('/api/auth/myhotel');return h.slug;}
async function loadPublic(){const d=await api(hroute(state.slug,'public'));state.hotel=d.hotel;state.catalog=d;if(!localStorage.getItem('stayos_lang')&&location.pathname.startsWith('/h/'))state.lang=d.hotel.language==='en'?'en':'he';document.title=`${d.hotel.name} | STAYOS`;document.documentElement.lang=state.lang;}
async function loadHotels(){state.hotels=await api('/api/owner/hotels');}
async function loadHotelManagement(){await loadPublic();}
function renderLogin(){document.title='STAYOS · Staff Sign In';APP.innerHTML=`<div class="loginpage"><div class="loginart"><div class="eyebrow" style="color:#eac995">A better stay begins here</div><h1>Hospitality,<br>beautifully connected.</h1><p>Bring your rooms, experiences, service requests and team into one carefully crafted guest experience.</p></div><div class="logincontent"><div class="loginbox">${brand()}<div class="eyebrow" style="margin-top:40px">Secure platform access</div><h1>Welcome back.</h1><p class="subtitle">Sign in to your STAYOS owner or hotel team account.</p><form id="loginForm"><div class="inputgroup"><label for="username">Username</label><input id="username" name="username" required autocomplete="username" placeholder="owner"></div><div class="inputgroup"><label for="password">Password</label><input id="password" type="password" name="password" required autocomplete="current-password" placeholder="Enter your password"></div><button class="btn primary full" type="submit">Sign in securely →</button></form><p class="mini muted">Platform owner: username <strong>owner</strong>, password from Railway variable <code>STAYOS_ADMIN_PASSWORD</code>.</p></div></div></div>`;}
function shell(name,nav,body){APP.innerHTML=`<div class="layout"><aside class="sidebar">${brand()}<div class="sidebar-label">${esc(name)}</div><nav class="nav">${nav}</nav><div class="sidefoot"><div>${esc(state.auth?.user?.display_name||'')}</div><div class="muted" style="margin:7px 0">${esc(state.auth?.user?.role||'')}</div><button data-action="changePassword" class="btn small" style="width:100%;margin:6px 0">Change password</button><button data-action="logout" class="btn small" style="width:100%">Sign out ↗</button></div></aside><main class="main">${body}</main></div>`;renderModal();}
async function loadBackupHealth(){
 const target=document.getElementById('platformBackupStatus');if(!target)return;
 try{const report=await api('/api/owner/backup-status');const last=report.last||{},success=last.status==='success';
 const summary=success?('Last backup: '+dateFmt(last.at)+(last.offsite_saved?' · Offsite copy saved':' · Local Volume only')):
   (last.status==='failed'?'Backup failed · '+esc(last.error||'check server logs'):'No backup completed yet');
 target.innerHTML=`<div class="panel backup-health ${success&&last.offsite_saved?'backup-ok':'backup-warning'}"><div class="eyebrow">DATA SAFETY · PLATFORM OWNER</div><h3>Backup status</h3><p class="subtitle">${esc(summary)}</p><p class="mini muted">${report.offsite_configured?'Offsite S3 storage configured.':'⚠ Offsite backup is not configured. Railway Volume alone is not disaster recovery.'}</p></div>`;
 }catch(e){target.textContent='Unable to retrieve backup status';}
}
function renderOwner(){document.title='STAYOS · Platform Owner';let nav=`<button class="active">✦ &nbsp; My Hotels</button>`;
 let cards=state.hotels.map(h=>`<article class="hotelcard">${img(h.hero_image)}<div class="inside"><div class="eyebrow">${h.demo?'UNOFFICIAL DEMO':'HOTEL ACCOUNT'}</div><h3>${esc(h.name)}</h3><p class="subtitle mini">${esc(h.location)} · ${esc(h.currency)} · ${h.active?'Active':'Inactive'}</p>${rowActions([`<button class="btn primary small" data-action="openHotel" data-slug="${esc(h.slug)}">Manage hotel →</button>`,`<a class="btn small" href="/h/${encodeURIComponent(h.slug)}/preview" target="_blank" rel="noopener">Guest preview ↗</a>`,`<button class="btn small" data-action="toggleHotel" data-id="${h.id}" data-active="${h.active}">${h.active?'Suspend':'Reactivate'}</button>`])}</div></article>`).join('');
 let body=`<div class="topbar">${pageIntro('STAYOS · PLATFORM OWNER','Your Hotels','Create, configure and oversee each hotel from one secure workspace.')}<button class="btn primary" data-action="newHotel">+ New hotel</button></div><div class="statgrid" style="grid-template-columns:repeat(2,minmax(0,230px))"><div class="stat"><span>Hotel accounts</span><strong>${state.hotels.length}</strong></div><div class="stat"><span>Active hotels</span><strong>${state.hotels.filter(h=>h.active&&!h.demo).length}</strong></div></div><div class="section-gap cards">${cards||empty()}</div><div id="platformBackupStatus" class="section-gap"></div>${state.hotels.some(h=>h.demo)?'<div class="notice section-gap">Sample properties are clearly marked. Suspend any concept property before onboarding real guests; create a new hotel account using its actual name, pricing and photos.</div>':''}`;
 shell('Platform owner',nav,body);loadBackupHealth();
}
function managerNav(){const tabs=[['dashboard','✧','Overview'],['room_history','📚','Room History'],['guests',...PERMS.guests],['requests',...PERMS.requests],['orders',...PERMS.orders],['folio',...PERMS.folio],['chat',...PERMS.chat],['room_types','🛌','Room Types'],['rooms','🚪','Physical Rooms'],['menu',...PERMS.menu],['activities',...PERMS.activities],['bookings','📆','Activity Bookings'],['amenities',...PERMS.amenities],['services',...PERMS.services],['branding',...PERMS.branding],['media',...PERMS.media],['staff','🔐','Team & Access'],['audit','📋','Audit Trail']];return tabs.filter(([id])=>{if(['dashboard'].includes(id))return true;if(id==='room_history')return ['guests','requests','orders','activities','chat','folio'].some(available);if(['staff','audit'].includes(id))return isOwner()||state.auth?.user?.role==='manager';return available(id==='room_types'?'rooms':id==='bookings'?'activities':id);}).map(([id,ico,label])=>`<button class="${state.tab===id?'active':''}" data-action="tab" data-tab="${id}"><span class="ico">${ico}</span>${label}</button>`).join('');}
function managerHeader(title,sub,extra=''){return `<div class="topbar">${pageIntro(state.hotel?.demo?'UNOFFICIAL CONCEPT DEMO · '+state.hotel?.location:'STAYOS HOTEL MANAGEMENT',title,sub)}<div class="topactions">${extra}<button id="receptionLive" class="btn" data-action="showEvents" aria-live="polite">🔔 Reception feed</button>${state.hotel?.demo&&canEdit('guests')?'<button class="btn primary" data-action="demoGuest">▶ Try guest demo</button>':''}<a class="btn" href="/h/${encodeURIComponent(state.slug)}/preview" target="_blank" rel="noopener">Guest preview ↗</a>${isOwner()?'<button class="btn" data-action="backOwner">All hotels</button>':''}<button class="btn" data-action="alerts">${state.alertsEnabled?'🔔 Alerts on':'🔕 Enable alerts'}</button></div></div>`;}
function renderManager(){if(!state.hotel)return;document.title='Manage '+state.hotel.name+' · STAYOS';let body=`${managerHeader(state.hotel.name, 'Guest experience, daily operations and content for this hotel.')}${state.hotel.demo?'<div class="notice">DEMO HOTEL — AI-generated images, fictional menu, prices, rooms and activities. No affiliation with the real Bayview Hotel.</div>':''}<div id="section">${empty('Loading your workspace...')}</div>`;shell(state.hotel.name,managerNav(),body);loadSection().catch(renderError);checkAlerts();}
async function loadSection(){const section=document.getElementById('section');if(!section)return;const tab=state.tab;try{
 if(tab==='dashboard'){let d=await hotelApi('dashboard');section.innerHTML=`<div class="statgrid">${[['Active stays',d.stays],['Guest requests',d.requests],['Orders',d.orders],['Rooms',d.rooms],['Open folio',fmt(d.open_folio,state.hotel.currency)]].map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="twocol section-gap"><div class="panel"><div class="eyebrow">FIRST STEPS</div><h3>Build the experience</h3><p class="subtitle">1. Upload hero and room images.<br>2. Add room types and physical rooms.<br>3. Build your restaurant menu and activities.<br>4. Create guest QR passes at check-in.</p>${rowActions([btn('Manage rooms','gotab:rooms','primary'),btn('Manage photos','gotab:media')])}</div><div class="panel"><div class="eyebrow">READY FOR GUESTS</div><h3>One QR. Every experience.</h3><p class="subtitle">Guests can request amenities, order to the pool or room, discover events and chat with reception. Charges remain open until the desk confirms settlement.</p>${rowActions([btn('Create a guest pass','gotab:guests','primary')])}</div></div>`;await loadReceptionPanel();return;}
 if(tab in CATALOG){let rows=await hotelApi(tab);section.innerHTML=renderCatalog(tab,rows);return;}
 if(tab==='branding'){let h=await hotelApi('branding');state.assets=available('media')?await hotelApi('media'):[];section.innerHTML=renderBranding(h);return;}
 if(tab==='media'){state.assets=await hotelApi('media');section.innerHTML=renderMedia();return;}
 if(tab==='staff'){state.staff=await hotelApi('staff');section.innerHTML=renderStaff();return;}
 if(tab==='guests'){let [stays,rooms]=await Promise.all([hotelApi('stays'),hotelApi('rooms')]);section.innerHTML=renderStays(stays,rooms);return;}
 if(tab==='requests'){section.innerHTML=renderRequests(await hotelApi('requests'));applyRoomFilter();return;}
 if(tab==='orders'){section.innerHTML=renderOrders(await hotelApi('orders'));applyRoomFilter();return;}
 if(tab==='bookings'){section.innerHTML=renderBookings(await hotelApi('bookings'));applyRoomFilter();return;}
 if(tab==='folio'){section.innerHTML=renderFolio(await hotelApi('folio'),await hotelApi('stays'));applyRoomFilter();return;}
 if(tab==='chat'){section.innerHTML=renderAdminChat(await hotelApi('chat'));await loadChatThread();return;}
 if(tab==='room_history'){let hist=await hotelApi('room-history?room='+encodeURIComponent(state.roomQuery));section.innerHTML=renderRoomHistory(hist);return;}
 if(tab==='audit'){section.innerHTML=renderAudit(await hotelApi('audit'));return;}
 }catch(e){section.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}}
function renderCatalog(resource,rows){let mainKeys={room_types:['name_en','name_he','size','max_guests'],rooms:['room','room_type_id','floor','notes'],menu:['name_en','name_he','category','price_cents'],activities:['name_en','starts','location','capacity'],amenities:['name_en','name_he','basis','quota'],services:['name_en','name_he','category','description_en']}[resource];let heading=`<div class="panel-heading"><div><div class="eyebrow">CONTENT MANAGEMENT</div><h2>${CATALOG[resource]}</h2><p class="subtitle">Add, edit or archive ${CATALOG[resource].toLowerCase()}. Changes appear for this hotel only.</p></div>${canEdit(resource==='room_types'?'rooms':resource)?`<button class="btn primary" data-action="newItem" data-resource="${resource}">+ Add new</button>`:'<span class="chip">View only</span>'}</div>`;let table=`<div class="tablewrap"><table class="data"><thead><tr><th>Photo</th>${mainKeys.map(k=>`<th>${LABEL[k]}</th>`).join('')}<th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.image?img(r.image,'thumb'):esc('—')}</td>${mainKeys.map(k=>`<td>${k==='price_cents'?fmt(r[k],state.hotel.currency):k==='starts'?dateFmt(r[k]):k==='room_type_id'?esc(r[k]):esc(String(r[k]??'').slice(0,70))}</td>`).join('')}<td><span class="chip ${r.active?'':'warn'}">${r.active?'Published':'Archived'}</span></td><td>${canEdit(resource==='room_types'?'rooms':resource)?rowActions([`<button class="btn small" data-action="editItem" data-resource="${resource}" data-id="${r.id}">Edit</button>`,r.active?`<button class="btn small danger" data-action="archiveItem" data-resource="${resource}" data-id="${r.id}">Archive</button>`:'']):'<span class="muted">Read only</span>'}</td></tr>`).join('')}</tbody></table></div>`;return `<div class="panel">${heading}${rows.length?table:empty()}</div>`;}
async function formResource(resource,id){let item={};if(id){let rows=await hotelApi(resource);item=rows.find(x=>x.id==id)||{};}let types=resource==='rooms'?await hotelApi('room_types'):[];if(FIELDS[resource].includes('image'))state.assets=available('media')?await hotelApi('media'):[];const controls=FIELDS[resource].map(k=>fieldHTML(resource,k,item[k],types));modal(`<div class="heading"><div><div class="eyebrow">${id?'EDIT':'NEW'} · ${CATALOG[resource].toUpperCase()}</div><h2>${id?'Edit':'Add'} ${CATALOG[resource]}</h2></div><button class="btn ghost" data-action="closeModal">✕</button></div><form id="resourceForm" data-resource="${resource}" data-id="${id||''}"><div class="formgrid">${controls.join('')}</div><div class="formfoot"><button type="button" class="btn" data-action="closeModal">Cancel</button><button type="submit" class="btn primary">Save changes →</button></div></form>`);}
function photoSelectorHTML(field,v,title){const assets=Array.from(new Set([...state.assets,...(String(v).startsWith('/media/')?[v]:[])]));const examples=state.hotel?.demo?PRESET:[];const opts=examples.map(f=>`<option value="${esc(f)}" ${v===f?'selected':''}>Example: ${esc(f)}</option>`).join('')+assets.map(f=>`<option value="${esc(f)}" ${v===f?'selected':''}>Hotel upload: ${esc(f.split('/').pop())}</option>`).join('');const choices=[...assets,...examples].map(f=>`<button type="button" class="photo-choice ${v===f?'selected':''}" data-action="chooseImage" data-target="${esc(field)}" data-value="${esc(f)}" title="Use this image">${img(f)}<span>${v===f?'✓ Current':'Select'}</span></button>`).join('');return `<div class="inputgroup wide photo-editor"><label>${esc(title)}</label><img class="media-preview" data-preview-for="${esc(field)}" src="${esc(pathImg(v))}" alt="Image preview"><select name="${esc(field)}" id="${esc(field)}Picker"><option value="" ${v?'':'selected'}>No image</option>${opts}</select><div class="photo-choices">${choices}</div>${canEdit('media')?`<label class="btn photo-upload">📷 Upload and replace <input type="file" accept="image/png,image/jpeg,image/webp" data-image-upload="${esc(field)}"></label>`:'<p class="mini muted">You can select an existing photo. Ask the hotel manager for permission to upload new images.</p>'}<p class="mini muted">Choose any photo, then click Save to publish. Uploaded files remain available in Media Library.</p></div>`;}
function fieldHTML(resource,k,val,types=[]){let v=val??'';if(k==='active'){return `<div class="inputgroup"><label>${LABEL[k]}</label><select name="active"><option value="1" ${v!==0?'selected':''}>Visible</option><option value="0" ${v===0?'selected':''}>Archived</option></select></div>`;}
 if(k==='room_type_id')return `<div class="inputgroup"><label>${LABEL[k]}</label><select name="${k}" required>${types.filter(t=>t.active).map(t=>`<option value="${t.id}" ${t.id===v?'selected':''}>${esc(t.name_en)} · max ${t.max_guests}</option>`).join('')}</select></div>`;
 if(k==='image')return photoSelectorHTML('image',v,'Photo / image for guests');
 if(k==='basis'||k==='period'||k==='category'){let opts=k==='basis'?['guest','room']:k==='period'?['daily','stay']:resource==='menu'?['drinks','food','snacks','desserts']:['info','spa','dining','facilities','other'];return `<div class="inputgroup"><label>${LABEL[k]}</label><select name="${k}">${opts.map(o=>`<option value="${o}" ${o===v?'selected':''}>${o}</option>`).join('')}</select></div>`;}
 if(k==='description_en'||k==='description_he'||k==='notes')return `<div class="inputgroup wide"><label>${LABEL[k]}</label><textarea name="${k}" maxlength="500">${esc(v)}</textarea></div>`;
 let isDate=['starts','ends'].includes(k),isNum=['max_guests','capacity','quota','price_cents'].includes(k),isMoney=k==='price_cents';return `<div class="inputgroup ${k==='name_en'?'':''}"><label>${LABEL[k]}</label><input name="${k}" ${isDate?'type="datetime-local"':isNum?'type="number" step="'+(isMoney?'.01':'1')+'" min="0"':'type="text"'} value="${esc(isDate?toLocal(v):isMoney?(Number(v||0)/100).toFixed(2):v)}" ${['name_en','room','starts','ends'].includes(k)?'required':''} ${isNum?'min="0"':''}></div>`;}
function renderBranding(h){const form=`<div class="formgrid">${[['name','Hotel display name'],['location','Location'],['currency','Currency (ISO code)'],['language','Default language (he/en)'],['welcome_en','English welcome'],['welcome_he','Hebrew welcome'],['description_en','English description'],['description_he','Hebrew description']].map(([k,label])=>`<div class="inputgroup ${k.startsWith('description')?'wide':''}"><label>${label}</label>${k.startsWith('description')?`<textarea name="${k}">${esc(h[k])}</textarea>`:`<input name="${k}" value="${esc(h[k])}">`}</div>`).join('')}<div class="inputgroup"><label>Primary brand color</label><input type="color" name="primary_color" value="${esc(h.primary_color)}"></div><div class="inputgroup"><label>Accent color</label><input type="color" name="accent_color" value="${esc(h.accent_color)}"></div>${['hero_image','logo_image'].map(k=>photoSelectorHTML(k,h[k],k==='hero_image'?'Guest homepage hero photo':'Hotel logo (optional)')).join('')}</div>`;return `<div class="twocol"><div class="panel"><div class="panel-heading"><div><div class="eyebrow">VISUAL IDENTITY</div><h2>Hotel Branding</h2></div></div><p class="subtitle" style="margin-bottom:23px">Personalize your property. Save to publish changes immediately for this hotel.</p><form id="brandingForm">${form}<div class="formfoot">${canEdit('branding')?'<button class="btn primary" type="submit">Save hotel branding</button>':'<span class="chip">View only</span>'}</div></form></div><div class="panel"><div class="eyebrow">LIVE BRAND PREVIEW</div><div class="hotelcard section-gap">${img(h.hero_image)}<div class="inside"><h2>${esc(h.name)}</h2><p class="subtitle">${esc(h.welcome_en)}</p><span class="chip">${esc(h.location)}</span></div></div><div class="notice info">Use actual photographs and approved descriptions from this hotel. Changes to published content are visible to guests immediately.</div></div></div>`;}
function renderMedia(){return `<div class="panel"><div class="panel-heading"><div><div class="eyebrow">HOTEL MEDIA</div><h2>Media Library</h2><p class="subtitle">Photos are stored under this hotel's account. Select an uploaded image when editing content.</p></div>${canEdit('media')?'<label class="btn primary" style="cursor:pointer">+ Upload photos <input type="file" accept="image/png,image/jpeg,image/webp" multiple data-image-upload="gallery" style="display:none"></label>':'<span class="chip">View only</span>'}</div><div class="eyebrow" style="margin-bottom:13px">YOUR UPLOADS</div><div class="uploads">${state.assets.length?state.assets.map(url=>`<div class="uploadcard">${img(url)}<small>${esc(url.split('/').pop())}</small><button data-action="copy" data-value="${esc(url)}" class="btn small full">Copy image URL</button></div>`).join(''):empty('No photos uploaded yet','Upload approved photographs of your property to use in the guest app.')}</div>${state.hotel?.demo?`<div class="divider"></div><div class="eyebrow">ILLUSTRATIVE CONCEPT IMAGES</div><p class="subtitle mini" style="margin-bottom:15px">Only for fictional concepts — never identify these as photos of a real hotel.</p><div class="uploads">${PRESET.map(i=>`<div class="uploadcard">${img(i)}<small>${i}</small><button data-action="copy" data-value="${i}" class="btn small full">Copy image name</button></div>`).join('')}</div>`:''}</div>`;}
function renderStaff(rows=state.staff){let table=`<div class="tablewrap"><table class="data"><thead><tr><th>User</th><th>Name</th><th>Role</th><th>Permissions</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.username)}</td><td>${esc(s.display_name)}</td><td>${esc(s.role)}</td><td>${esc(s.role==='manager'?'All hotel permissions':s.permissions.join(', '))}</td><td>${s.active?'Active':'Disabled'}</td><td><button class="btn small" data-action="editStaff" data-id="${s.id}">Edit permissions</button></td></tr>`).join('')}</tbody></table></div>`;return `<div class="panel"><div class="panel-heading"><div><div class="eyebrow">ACCESS CONTROL</div><h2>Team & Permissions</h2><p class="subtitle">Staff accounts receive no edit access by default. Managers assign only what is needed.</p></div><button data-action="newStaff" class="btn primary">+ Add team member</button></div>${rows.length?table:empty('No staff users yet','Add the first manager or reception employee.')}</div>`;}
function staffModal(id){let s=state.staff.find(x=>x.id===id)||{};let edit=!!id;let allowedManager=isOwner();let checks=Object.entries(PERMS).map(([k,v])=>{let val=(s.permissions||[]).some(x=>x==='edit:'+k||x===k)?'edit':(s.permissions||[]).includes('view:'+k)?'view':'none';return `<div class="inputgroup"><label>${v[0]} ${v[1]}</label><select data-perm="${k}"><option value="none" ${val==='none'?'selected':''}>No access</option><option value="view" ${val==='view'?'selected':''}>View only</option><option value="edit" ${val==='edit'?'selected':''}>View & edit</option></select></div>`;}).join('');modal(`<div class="heading"><div><div class="eyebrow">TEAM ACCESS</div><h2>${edit?'Edit':'Add'} Team Member</h2></div><button class="btn ghost" data-action="closeModal">✕</button></div><form id="staffForm" data-id="${id||''}"><div class="formgrid">${!edit?`<div class="inputgroup"><label>Username (unique across platform)</label><input name="username" required placeholder="reception.bayview"></div><div class="inputgroup"><label>Display name</label><input name="display_name" required placeholder="Front desk team"></div><div class="inputgroup"><label>Role</label><select name="role"><option value="staff">Staff</option>${allowedManager?'<option value="manager">Hotel manager (full access)</option>':''}</select></div>`:''}<div class="inputgroup"><label>${edit?'New password (optional)':'Temporary password (12+ characters)'}</label><input type="password" minlength="${edit?0:12}" name="password" ${edit?'':'required'} autocomplete="new-password"></div>${edit?`<div class="inputgroup"><label>Account status</label><select name="active"><option value="1" ${s.active?'selected':''}>Active</option><option value="0" ${!s.active?'selected':''}>Disable access</option></select></div>`:''}</div><div class="divider"></div><div class="eyebrow">GRANULAR STAFF PERMISSIONS</div><div class="formgrid">${checks}</div><p class="mini muted">Only the platform owner can create hotel managers. Manager accounts receive all hotel permissions. Staff cannot create other users.</p><div class="formfoot"><button type="button" data-action="closeModal" class="btn">Cancel</button><button class="btn primary" type="submit">Save team access</button></div></form>`);}
function renderStays(stays,rooms){let table=`<div class="tablewrap"><table class="data"><thead><tr><th>Room</th><th>Guests</th><th>Start</th><th>Ends</th><th>Status</th><th>QR & access</th></tr></thead><tbody>${stays.map(x=>`<tr><td><strong>${esc(x.room)}</strong></td><td>${x.guests}</td><td>${dateFmt(x.start)}</td><td>${dateFmt(x.ends)}</td><td><span class="chip ${x.revoked?'warn':''}">${x.revoked?'Revoked':'Active'}</span></td><td>${rowActions([`<button data-action="showQr" data-id="${x.id}" class="btn small">Show QR</button>`,x.revoked||!canEdit('guests')?'':`<button data-action="revokeStay" data-id="${x.id}" class="btn small danger">Revoke</button>`])}</td></tr>`).join('')}</tbody></table></div>`;return `<div class="panel"><div class="panel-heading"><div><div class="eyebrow">RECEPTION & CHECK-IN</div><h2>Guest Access Passes</h2><p class="subtitle">Create a time-limited access pass tied to a physical room and selected guest services.</p></div>${canEdit('guests')?'<button data-action="newStay" class="btn primary">+ Create QR pass</button>':'<span class="chip">View only</span>'}</div>${stays.length?table:empty('No guest passes','Create a new guest pass from reception.')}</div>`;}
async function stayModal(){let rooms=(await hotelApi('rooms')).filter(r=>r.active),types=await hotelApi('room_types');if(!rooms.length){notify('Add a room type and a physical room first.',true);return;}modal(`<div class="heading"><div><div class="eyebrow">RECEPTION</div><h2>New Guest QR Access</h2></div><button data-action="closeModal" class="btn ghost">✕</button></div><form id="stayForm"><div class="formgrid"><div class="inputgroup"><label>Physical room</label><select name="room_id">${rooms.map(r=>`<option value="${r.id}">Room ${esc(r.room)} · ${esc(types.find(t=>t.id===r.room_type_id)?.name_en||'')}</option>`).join('')}</select></div><div class="inputgroup"><label>Number of guests</label><input type="number" name="guests" min="1" max="12" value="2" required></div><div class="inputgroup"><label>Access starts</label><input type="datetime-local" name="start" value="${getLocalDate(0)}" required></div><div class="inputgroup"><label>Access ends</label><input type="datetime-local" name="ends" value="${getLocalDate(2)}" required></div></div><div class="divider"></div><div class="eyebrow">ALLOWED GUEST FEATURES</div><div class="checkrows">${[['requests','Amenities'],['orders','Food orders'],['activities','Activities'],['chat','Reception chat']].map(([k,l])=>`<label><input type="checkbox" name="zones" value="${k}" checked> ${l}</label>`).join('')}</div><div class="formfoot"><button type="button" class="btn" data-action="closeModal">Cancel</button><button type="submit" class="btn primary">Generate QR access →</button></div></form>`);}
function showPass(stay){let url=location.origin+'/h/'+encodeURIComponent(state.slug)+'/guest?token='+encodeURIComponent(stay.token);modal(`<div class="heading"><div><div class="eyebrow">PERSONAL ROOM ACCESS</div><h2>Room ${esc(stay.room||'')}</h2></div><button class="btn ghost" data-action="closeModal">✕</button></div><img class="qrcode" src="${hroute(state.slug,'manage/stays/'+stay.id+'/qr')}" alt="Guest QR code"><div class="inputgroup"><label>Guest link</label><input readonly value="${esc(url)}"></div><div class="formfoot"><button class="btn primary" data-action="copy" data-value="${esc(url)}">Copy guest link</button></div><div class="notice">This URL is a private room access pass. Only share it with the guest staying in this room.</div>`);}
const AREA_NAMES={room:{he:'חדר',en:'Room'},pool:{he:'בריכה',en:'Pool'},lobby:{he:'לובי',en:'Lobby'},beach:{he:'חוף',en:'Beach'},restaurant:{he:'מסעדה',en:'Restaurant'},garden:{he:'גינה',en:'Garden'}};
function deliveryLabel(area,room,lang='en'){let base=AREA_NAMES[area]?.[lang]||String(area||'');return (area==='room'&&room)?base+' '+esc(room):base;}
function roomLink(room){return `<button class="room-link" data-action="openRoom" data-room="${esc(room)}" title="View complete room history">Room ${esc(room)} ↗</button>`;}
function roomFilterUI(){return `<label class="room-filter-label">🔎 Find room <input type="search" id="roomFilter" placeholder="e.g. 204" value="${esc(state.roomFilter)}" aria-label="Search room number"></label>`;}
function applyRoomFilter(){const value=(state.roomFilter||'').trim().toLowerCase();let count=0;document.querySelectorAll('[data-room-row]').forEach(row=>{const yes=String(row.dataset.roomRow||'').toLowerCase().includes(value);row.hidden=!yes;if(yes)count++;});let status=document.getElementById('roomFilterStatus');if(status)status.textContent=count+' matching entries';}
function kindUI(t){return {order:['🍽','Food order'],request:['🛎','Room amenity'],booking:['🌴','Activity'],message:['💬','Guest message'],charge:['💳','Room charge']}[t]||['✦','Activity'];}
function receptionDetails(e){if(e.type==='order')return deliveryLabel(e.area,e.room)+' · '+(e.detail||'')+(e.note?' · '+e.note:'');return e.label||'';}
const EVENT_PERM={order:'orders',request:'requests',booking:'activities',message:'chat'};
function eventHealthStatus(){
 const problem=state.lastAlertFailure>0 && (Date.now()-state.lastAlertSuccess>25000);
 return `<span id="receptionConnection" class="connection-indicator ${problem?'connection-error':'connection-ok'}" role="status">${problem?'⚠ Connection interrupted':'● Connected · checking every 4s'}</span>`;
}
function receptionEventHTML(e,compact=false){
 let [ico,title]=kindUI(e.type);
 const canHandle=canEdit(EVENT_PERM[e.type]||'');
 const claimed=e.assigned_to?'Assigned to '+esc(e.assignee_name||'team member'):'';
 const status=e.acknowledged_at?'✓ Accepted by '+esc(e.acknowledged_name||'staff'):(e.overdue?'⚠ Overdue · '+e.age_minutes+' min':e.action_needed?'Awaiting confirmation':'Completed');
 return `<article class="reception-event ${compact?'compact':''} ${e.overdue?'event-overdue':''} ${e.acknowledged_at?'event-accepted':''}">
 <span class="event-icon" aria-hidden="true">${ico}</span>
 <div class="event-body"><div class="event-title">${esc(title)} · <strong>Room ${esc(e.room)}</strong></div>
 <div class="event-summary">${esc(e.label||'')}${e.type==='order'?`<br><b>Deliver to: ${esc(deliveryLabel(e.area,e.room))}</b>${e.detail?' · '+esc(e.detail):''}${e.note?'<br>Note: '+esc(e.note):''}`:''}</div>
 <div class="event-meta"><span class="event-status">${status}</span>${claimed?`<span class="event-assignee">${claimed}</span>`:''}<small>${dateFmt(e.created)}</small></div></div>
 <div class="event-actions">${canHandle&&e.action_needed&&!e.acknowledged_at?`<button class="btn small primary" data-action="acceptEvent" data-type="${esc(e.type)}" data-id="${e.id}">✓ Accept</button>`:''}
 ${canHandle&&!e.assigned_to?`<button class="btn small" data-action="claimEvent" data-type="${esc(e.type)}" data-id="${e.id}">Assign to me</button>`:''}
 ${canHandle&&(isOwner()||state.auth?.user?.role==='manager')?`<button class="btn small" data-action="assignEvent" data-type="${esc(e.type)}" data-id="${e.id}">Assign staff</button>`:''}
 <button class="btn small" data-action="openRoom" data-room="${esc(e.room)}">Room history ↗</button></div></article>`;
}
function renderLiveBoard(events){
 const list=events||[],pending=list.filter(e=>e.action_needed&&!e.acknowledged_at);
 const critical=pending.filter(e=>e.overdue).length;
 const ordered=[...list].sort((a,b)=>(Number(b.overdue)-Number(a.overdue))||(Number(b.action_needed&&!b.acknowledged_at)-Number(a.action_needed&&!a.acknowledged_at))||b.created.localeCompare(a.created));
 return `<div class="panel reception-board section-gap" id="liveBoard"><div class="panel-heading"><div><div class="eyebrow">● STAYOS LIVE RECEPTION</div><h2>Front desk command center</h2><p class="subtitle">Live guest orders and messages. Accept each new request so nothing is missed.</p></div>
 <div class="actions"><span id="livePendingCount" class="chip ${pending.length?'warn':''}">${pending.length} need action</span><span id="liveOverdueCount" class="chip ${critical?'warn':''}">${critical} overdue</span><button class="btn small" data-action="showEvents">View all</button></div></div>
 <div class="reception-heartbeat">${eventHealthStatus()}</div>
 <div id="liveBoardItems">${ordered.length?ordered.slice(0,12).map(e=>receptionEventHTML(e,true)).join(''):empty('No guest activity','New orders, messages and requests will appear here.')}</div></div>`;
}
async function loadReceptionPanel(){if(!state.auth?.authenticated)return;let events=await hotelApi('events');state.receptionEvents=events;const section=document.getElementById('section');if(section&&state.tab==='dashboard')section.insertAdjacentHTML('afterbegin',renderLiveBoard(events));}
function refreshLiveBoard(){
 const node=document.getElementById('liveBoardItems');if(!node)return;
 const events=state.receptionEvents||[];
 const pending=events.filter(e=>e.action_needed&&!e.acknowledged_at),critical=pending.filter(e=>e.overdue);
 const sorted=[...events].sort((a,b)=>(Number(b.overdue)-Number(a.overdue))||(Number(b.action_needed&&!b.acknowledged_at)-Number(a.action_needed&&!a.acknowledged_at))||b.created.localeCompare(a.created));
 node.innerHTML=sorted.slice(0,12).map(e=>receptionEventHTML(e,true)).join('')||empty('No guest activity');
 const a=document.getElementById('livePendingCount');if(a)a.textContent=pending.length+' need action';
 const b=document.getElementById('liveOverdueCount');if(b)b.textContent=critical.length+' overdue';
 const c=document.getElementById('receptionConnection');if(c)c.outerHTML=eventHealthStatus();
}
function recordEventRead(){const marks={};for(let e of state.receptionEvents||[])marks[e.type]=Math.max(marks[e.type]||0,e.id);state.receptionSeen=marks;state.unreadEvents=0;try{localStorage.setItem('stayos_seen_'+state.slug+'_'+state.auth?.user?.id,JSON.stringify(marks));}catch{}refreshLiveBoard();}
function receptionPopup(e){const box=document.createElement('button');box.type='button';box.className='reception-popup';box.dataset.action='openRoom';box.dataset.room=e.room;box.innerHTML=`<strong>🔔 New ${esc(kindUI(e.type)[1])} · Room ${esc(e.room)}</strong><span>${esc(e.label||'')}</span>${e.type==='order'?`<span>📍 ${esc(deliveryLabel(e.area,e.room))}${e.detail?' · '+esc(e.detail):''}</span>`:''}<small>Open room history →</small>`;TOAST.prepend(box);setTimeout(()=>box.remove(),14000);}
function renderRoomHistory(data){const room=data.room||'';let events=data.entries||[];let options=(data.rooms||[]).map(r=>`<option value="${esc(r)}"></option>`).join('');let blocks=events.map(e=>{let [ico,title]=kindUI(e.type);let summary='';if(e.type==='order')summary=`<strong>${(e.items||[]).map(x=>esc(x.qty+'× '+x.name)).join(' · ')}</strong><div>📍 ${esc(deliveryLabel(e.area,room))}${e.detail?' · '+esc(e.detail):''}</div>${e.note?'<div>📝 '+esc(e.note)+'</div>':''}<div>${fmt(e.total_cents,state.hotel.currency)}</div>`;
else if(e.type==='request')summary=`${esc(e.qty)}× ${esc(e.name_en||e.name_he)} · ${esc(e.status)}`;
else if(e.type==='booking')summary=`${esc(e.qty)}× ${esc(e.name_en||e.name_he)} · ${fmt((e.price_cents||0)*e.qty,state.hotel.currency)} ${e.price_cents?'':'(Free)'}<div>${esc(e.location||'')} · ${dateFmt(e.starts)}</div>`;
else if(e.type==='message')summary=`${esc(e.sender)}: ${esc(e.body)}`;
else if(e.type==='charge')summary=`${esc(e.description)} · ${fmt(e.amount_cents,state.hotel.currency)}`;
return `<article class="history-entry"><span class="event-icon">${ico}</span><div><div class="eyebrow">${title} · Stay #${e.stay_id} · ${dateFmt(e.created)}</div><h3>${summary}</h3><div class="mini muted">Status: ${esc(e.status||'recorded')}</div></div></article>`;}).join('');return `<div class="panel"><div class="panel-heading"><div><div class="eyebrow">ROOM ACTIVITY RECORD</div><h2>Complete history by room</h2><p class="subtitle">Food and drink deliveries, amenities, free and paid activities, reception chat and charges.</p></div><div class="actions"><button data-action="refresh" class="btn">Refresh</button><button data-action="markEventsRead" class="btn">Mark alerts read</button></div></div><div class="room-search-wrap"><label class="inputgroup"><span>Search room number</span><input type="search" id="roomHistoryInput" list="hotelRoomNumbers" value="${esc(room)}" placeholder="Type room number, e.g. 204" autocomplete="off"></label><datalist id="hotelRoomNumbers">${options}</datalist><button class="btn primary" data-action="searchRoom">Search</button></div>${room?`<div class="history-heading"><h2>${roomLink(room)} · ${events.length} records</h2><span class="chip">Includes previous stays</span></div>${blocks||empty('No activity recorded','This room has no recorded orders, requests or messages yet.')}`:'<div class="notice info">Enter a room number to see its complete history. Each entry remains linked to its original stay.</div>'}</div>`;}
function renderRequests(rows){return `<div class="panel"><div class="panel-heading"><div><div class="eyebrow">HOUSEKEEPING</div><h2>Guest Requests</h2></div>${roomFilterUI()}<button class="btn" data-action="refresh">Refresh</button></div>${rows.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Room</th><th>Request</th><th>Qty</th><th>Created</th><th>Current status</th><th>Update</th></tr></thead><tbody>${rows.map(r=>`<tr data-room-row="${esc(r.room)}"><td>${roomLink(r.room)}</td><td>${esc(r.item)}</td><td>${r.qty}</td><td>${dateFmt(r.created)}</td><td>${esc(r.status)}</td><td><select data-status="requests" data-id="${r.id}" ${!canEdit('requests')?'disabled title="View only"':''}>${['new','progress','done','cancelled'].map(s=>`<option ${s===r.status?'selected':''} value="${s}">${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:empty('All clear','No guest requests received yet.')}</div>`;}
function renderBookings(rows){return `<div class="panel"><div class="panel-heading"><div><div class="eyebrow">GUEST ACTIVITIES</div><h2>Activity Bookings</h2><p class="subtitle">Guest activity registrations appear here immediately and are included in reception alerts.</p></div>${roomFilterUI()}<button class="btn" data-action="refresh">Refresh</button></div>${rows.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Booking</th><th>Room</th><th>Experience</th><th>Guests</th><th>Starts</th><th>Total</th><th>Status</th><th>Booked</th></tr></thead><tbody>${rows.map(r=>`<tr data-room-row="${esc(r.room)}"><td>#${r.id}</td><td>${roomLink(r.room)}</td><td>${esc(r.activity)}</td><td>${r.qty}</td><td>${dateFmt(r.starts)}</td><td>${fmt(r.total_cents,state.hotel.currency)}</td><td><span class="chip ${r.cancelled_at?'warn':''}">${r.cancelled_at?'Cancelled':'Booked'}</span></td><td>${dateFmt(r.created)}</td></tr>`).join('')}</tbody></table></div>`:empty('No activity bookings','Guest registrations will appear here as soon as they are confirmed.')}</div>`;}
function renderOrders(rows){return `<div class="panel"><div class="panel-heading"><div><div class="eyebrow">FOOD & BEVERAGE</div><h2>Orders & Delivery</h2></div>${roomFilterUI()}<button data-action="refresh" class="btn">Refresh</button></div>${rows.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Order</th><th>Room</th><th>Deliver to</th><th>Items</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody>${rows.map(r=>`<tr data-room-row="${esc(r.room)}"><td>#${r.id}</td><td>${roomLink(r.room)}</td><td><strong>${deliveryLabel(r.area,r.room,'en')}</strong><div class="mini muted">${esc(r.detail||'')} ${r.note?' · '+esc(r.note):''}</div></td><td>${r.lines.map(l=>`<div>${esc(l.qty)}× ${esc(l.name)}</div>`).join('')}</td><td>${fmt(r.total_cents,state.hotel.currency)}</td><td>${esc(r.status)}</td><td><select data-status="orders" data-id="${r.id}" ${!canEdit('orders')?'disabled title="View only"':''}>${['new','preparing','on_way','delivered','cancelled'].map(s=>`<option value="${s}" ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:empty('No orders yet','Your first guest menu order will show up here.')}</div>`;}
function renderFolio(rows,stays){
 const due=rows.filter(x=>x.status==='open').reduce((a,x)=>a+x.amount_cents,0);
 const seen=new Set(); const staysWithCharges=[];
 for(const s of stays){if(seen.has(s.id))continue;seen.add(s.id);const charges=rows.filter(r=>r.stay_id===s.id);
 const amount=charges.filter(r=>r.status==='open').reduce((a,r)=>a+r.amount_cents,0);
 if(charges.length||!s.revoked)staysWithCharges.push({...s,openAmount:amount,chargeCount:charges.length});}
 const stayCards=staysWithCharges.map(s=>`<div class="checkout-row" data-room-row="${esc(s.room)}"><div><strong>Room ${esc(s.room)} · Stay #${s.id}</strong><div class="mini muted">${dateFmt(s.start)} – ${dateFmt(s.ends)} · ${s.revoked?'Access closed':'Guest access active'}</div></div><div><strong>${fmt(s.openAmount,state.hotel.currency)}</strong><div class="mini muted">${s.chargeCount} recorded charges</div></div><button class="btn ${s.openAmount>0?'primary':''} small" data-action="reviewCheckout" data-id="${s.id}">${s.openAmount>0?'Review checkout':'View statement'}</button></div>`).join('');
 return `<div class="panel"><div class="panel-heading"><div><div class="eyebrow">RECEPTION · CHECKOUT</div><h2>Room Folio</h2><p class="subtitle">Every guest charge is recorded under its stay. Collect money using your existing hotel terminal or cash register, then confirm here.</p></div>${roomFilterUI()}<div class="chip">Uncollected: ${fmt(due,state.hotel.currency)}</div></div>
 <div class="notice info">STAYOS is a checkout ledger only — it does not charge credit cards, receive money, or issue a tax receipt.</div>
 <div class="checkout-list section-gap">${stayCards||empty('No active stays or charges','Create a guest QR at reception to start recording activity.')}</div></div>`;
}
async function reviewCheckout(stayId){
 const d=await hotelApi('checkout?stay_id='+encodeURIComponent(stayId));const room=d.stay.room;
 const line=(r)=>`<tr><td>${esc(r.description)}${r.delivery_area?`<div class="mini muted">📍 ${esc(deliveryLabel(r.delivery_area,room))}${r.delivery_detail?' · '+esc(r.delivery_detail):''}</div>`:''}</td><td>${fmt(r.amount_cents,d.currency)}</td><td>${esc(r.status==='open'?'Uncollected':r.status==='paid'?'Collected':'Voided')}</td></tr>`;
 const free=[...d.free_bookings.map(b=>({label:esc(b.name_en||b.name_he)+' × '+b.qty,status:b.cancelled_at?'Cancelled':'Booked'})),...d.requests.map(r=>({label:esc(r.name_en||r.name_he)+' × '+r.qty,status:esc(r.status)}))];
 const pending=d.pending_orders.length?`<div class="notice">⚠ ${d.pending_orders.length} order(s) still being processed. Confirm delivery or cancellation before final checkout.</div>`:'';
 const settled=d.settlements.map(x=>`<div class="mini">${dateFmt(x.collected_at)} · ${fmt(x.amount_cents,d.currency)} · ${esc(x.method)}${x.reference?' · Ref: '+esc(x.reference):''} · ${esc(x.collected_by)}</div>`).join('')||'<p class="mini muted">No collection recorded yet</p>';
 modal(`<div class="heading"><div><div class="eyebrow">CHECKOUT STATEMENT</div><h2>Room ${esc(room)} · Stay #${stayId}</h2><p class="subtitle">This is a hotel operations statement, not a tax invoice.</p></div><button class="btn ghost" data-action="closeModal">✕</button></div>
 <div class="statgrid checkout-totals"><div class="stat"><span>To collect</span><strong>${fmt(d.totals.open,d.currency)}</strong></div><div class="stat"><span>Previously collected</span><strong>${fmt(d.totals.paid,d.currency)}</strong></div><div class="stat"><span>Cancelled charges</span><strong>${fmt(d.totals.void,d.currency)}</strong></div></div>
 <div class="tablewrap section-gap"><table class="data"><thead><tr><th>Charge</th><th>Amount</th><th>Status</th></tr></thead><tbody>${d.charges.map(line).join('')||'<tr><td colspan="3">No chargeable items</td></tr>'}</tbody></table></div>
 <h3 style="margin-top:17px">Complimentary services & activities</h3><div class="checkout-free">${free.map(r=>`<div class="itemrow"><span>${r.label}</span><span class="chip">${r.status}</span></div>`).join('')||'<p class="mini muted">No complimentary items</p>'}</div>
 <h3 style="margin-top:17px">Recorded external collections</h3>${settled}${pending}
 ${d.totals.open>0&&canEdit('folio')?`<form id="checkoutConfirmForm" data-stay="${stayId}" data-amount="${d.totals.open}"><div class="formgrid"><div class="inputgroup"><label>Collected using</label><select name="method"><option value="terminal">Hotel card terminal</option><option value="cash">Cash</option><option value="other">Other hotel payment method</option></select></div><div class="inputgroup"><label>Hotel receipt / reference (optional)</label><input name="reference" maxlength="80" placeholder="No card details"></div></div><label class="checkrow"><input type="checkbox" required name="collected" value="yes"> I confirm that the hotel has already collected ${fmt(d.totals.open,d.currency)} outside STAYOS and this guest stay can be closed.</label><div class="formfoot"><button class="btn primary" type="submit">Record collected & close guest pass</button></div></form>`:(canEdit('folio')&&!d.stay.revoked?`<div class="notice info section-gap">No outstanding amount to collect. Nothing will be marked paid.</div><div class="formfoot"><button class="btn primary" data-action="closeZeroStay" data-id="${stayId}" type="button">Close guest pass (zero balance)</button></div>`:'<div class="notice info section-gap">No outstanding amount to collect.</div>')}
 <div class="formfoot"><button class="btn" type="button" data-action="printCheckout">Print statement</button><button class="btn" type="button" data-action="closeModal">Close</button></div>`);
}

function renderAdminChat(rows){const selected=state.selectedThread||rows[0]?.stay_id||0;state.selectedThread=selected;return `<div class="twocol"><div class="panel"><div class="panel-heading"><h2>Guest Conversations</h2><button class="btn small" data-action="refresh">Refresh</button></div>${rows.length?rows.map(t=>`<button class="btn ${t.stay_id===selected?'primary':''}" style="display:flex;width:100%;margin:9px 0;justify-content:space-between" data-action="selectThread" data-id="${t.stay_id}">Room ${esc(t.room)} <span>${t.count} messages</span></button>`).join(''):empty('No conversations yet')}</div><div class="panel" id="thread">${selected?'<div class="muted">Loading conversation...</div>':empty('Select a room')}</div></div>`;}
async function loadChatThread(){if(!state.selectedThread)return;let messages=await hotelApi('chat?stay_id='+state.selectedThread);let el=document.getElementById('thread');if(!el)return;el.innerHTML=`<div class="eyebrow">LIVE RECEPTION CHAT</div><h2 style="margin-bottom:15px">Stay #${state.selectedThread}</h2><div class="guest"><div class="chatbox">${messages.map(m=>`<div class="bubble ${m.sender==='reception'?'mine':''}"><strong class="mini">${esc(m.sender)}</strong><div>${esc(m.body)}</div><small>${dateFmt(m.created)}</small></div>`).join('')}</div></div>${canEdit('chat')?`<form class="flex" id="staffChatForm" style="margin-top:13px"><input name="body" placeholder="Reply to your guest..." required maxlength="1500" style="flex:1;min-width:0;padding:12px;border:1px solid #ddd;border-radius:10px"><button class="btn primary" type="submit">Send</button></form>`:''}`;el.querySelector('.chatbox').scrollTop=999999;}
function renderAudit(rows){return `<div class="panel"><div class="eyebrow">ACCOUNTABILITY</div><h2>Activity Log</h2><p class="subtitle" style="margin-bottom:20px">Records who changed content, staff permissions and guest operations.</p>${rows.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Date</th><th>Staff</th><th>Action</th><th>Area</th><th>Item</th><th>Details</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${dateFmt(a.created)}</td><td>${esc(a.display_name||'System')}</td><td>${esc(a.action)}</td><td>${esc(a.entity)}</td><td>${esc(a.entity_id)}</td><td>${esc(a.details)}</td></tr>`).join('')}</tbody></table></div>`:empty('No changes recorded yet')}</div>`;}
const L={he:{home:'בית',dining:'תפריט',amenities:'שירותים',activities:'פעילויות',chat:'צ׳אט',my:'ההזמנות שלי',room:'חדר',welcome:'ברוכים הבאים',discover:'לגלות את המלון',services:'כל שירותי המלון',roomservice:'שירות חדרים',chatreception:'צ׳אט עם הקבלה',more:'לכל האפשרויות',order:'הוספה להזמנה',book:'הרשמה לפעילות',request:'הזמן שירות',locations:'בחרו לאן לשלוח את ההזמנה',cart:'סיכום הזמנה',checkout:'שליחת הזמנה לחיוב החדר',addhome:'הוספה למסך הבית',view:'הצג',preview:'תצוגה מקדימה — להזמנות נדרשת גישת QR פעילה',requests:'בקשות',messages:'הודעות',roominfo:'החדר שלכם',sent:'נשלח לקבלה',empty:'אין פריטים להצגה',balance:'יתרה לתשלום בצ׳ק־אאוט',info:'מידע ושירותים'},en:{home:'Home',dining:'Dining',amenities:'Amenities',activities:'Activities',chat:'Chat',my:'My Requests',room:'Room',welcome:'Welcome',discover:'Discover the resort',services:'Hotel Experiences',roomservice:'Room Service',chatreception:'Chat with Reception',more:'Explore all',order:'Add to order',book:'Book experience',request:'Request service',locations:'Choose delivery location',cart:'Your order',checkout:'Send order · Charge to room',addhome:'Add to home screen',view:'View',preview:'Preview only — guest QR access required to order',requests:'Requests',messages:'Messages',roominfo:'Your Room',sent:'Sent to reception',empty:'Nothing to show yet',balance:'Balance payable at checkout',info:'Hotel Info'}};
function t(k){return L[state.lang]?.[k]||k;}function pick(r,k){return r?.[k+'_'+state.lang]||r?.[k+'_en']||'';}
function guestAllowed(feature){return !!state.guest && (state.guest.stay.zones||[]).includes(feature);}
function renderGuest(){if(!state.hotel)return;const manifest=document.querySelector('link[rel=manifest]');if(manifest)manifest.href=(state.guest&&state.token)?hroute(state.slug,'guest/'+encodeURIComponent(state.token)+'/manifest'):'/manifest.webmanifest';document.title=state.hotel.name+' · STAYOS';document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='he'?'rtl':'ltr';document.body.classList.add('guestmode');const ht=state.hotel;const room=state.guest?.stay?.room;
 let hero=`<div class="guest-header">${img(ht.hero_image,'bg')}<div class="guest-header-content"><div class="guest-top">${ht.logo_image?`<div class="brand">${img(ht.logo_image,'', 'width:55px;height:55px;border-radius:50%;object-fit:contain;background:white;padding:4px')}<span class="brandtext">${esc(ht.name.replace(' — Concept Demo',''))}</span></div>`:brand()}<div class="flex"><select id="langPicker" aria-label="Language"><option value="he" ${state.lang==='he'?'selected':''}>עברית</option><option value="en" ${state.lang==='en'?'selected':''}>English</option></select></div></div><div class="guest-headline"><div class="eyebrow" style="color:#f7d4a2">${esc(ht.location)}</div><h1>${esc(ht.name.replace(' — Concept Demo',''))}</h1><p>${esc(pick(ht,'welcome')||'Welcome to your stay')}${room?' · '+t('room')+' '+esc(room):''}</p></div></div></div>`;
 const tabs=[['home','⌂',t('home')],['dining','♨',t('dining')],['amenities','♧',t('amenities')],['activities','☼',t('activities')],['chat','✉',t('chat')],['my','▤',t('my')]];
 let section=state.guestTab==='home'?guestHome():state.guestTab==='dining'?guestDining():state.guestTab==='amenities'?guestAmenities():state.guestTab==='activities'?guestActivities():state.guestTab==='chat'?guestChatShell():guestMyShell();
 APP.innerHTML=`<div class="guest ${state.lang==='he'?'rtl':''}" style="--guestgreen:${esc(ht.primary_color)};--guestgold:${esc(ht.accent_color)}">${ht.demo?`<div class="previewribbon">✧ ${state.lang==='he'?'הדמיה לא רשמית · התמונות והמחירים להמחשה בלבד':'Unofficial concept demo · AI imagery & fictional pricing'}</div>`:''}${hero}<main class="guest-main">${!state.guest?`<div class="notice">${t('preview')}. ${state.lang==='he'?'כדי לבצע הזמנה ולראות אותה בקבלה, נכנסים דרך QR אישי.':'Use a personal reception QR to send orders.'}${ht.demo&&state.auth?.authenticated&&canEdit('guests')?` <button class="btn small primary" data-action="demoGuest">${state.lang==='he'?'הפעלת אורח דמו להזמנות':'Start demo guest order'}</button>`:''}</div>`:''}${section}</main><nav class="guestnav">${tabs.map(([tab,ico,label])=>`<button data-action="guestTab" data-tab="${tab}" class="${state.guestTab===tab?'active':''}"><b>${ico}</b><span>${label}</span></button>`).join('')}</nav></div>`;
 if(state.guestTab==='chat'&&state.guest)loadGuestChat().catch(renderError);if(state.guestTab==='my'&&state.guest)loadGuestMy().catch(renderError);renderModal();if(state.guest&&state.lastGuestReplyId===null)checkAlerts();}
function guestHome(){const d=state.catalog||{},types=d.room_types||[],svc=d.services||[];const links=[['dining','♨',t('dining')],['amenities','♧',t('amenities')],['activities','☼',t('activities')],['chat','✉',t('chatreception')],['my','▤',t('my')],['install','⬇',t('addhome')]];
 return `<div class="eyebrow">${state.lang==='he'?'חוויית אירוח אישית':'YOUR PERSONAL HOTEL CONCIERGE'}</div><h2 class="gtitle">${t('welcome')} ${state.guest?'· '+t('room')+' '+esc(state.guest.stay.room):''}</h2><div class="quickgrid">${links.map(([key,ico,label])=>`<button class="quick" data-action="${key==='install'?'install':'guestTab'}" ${key!=='install'?`data-tab="${key}"`:''}><span class="ico">${ico}</span><span>${label}</span></button>`).join('')}</div><div class="guest-banner">${img(state.hotel.hero_image)}<div class="overlay"><div><div class="eyebrow" style="color:#f5c98c">${state.lang==='he'?'חוויות במלון':'HOTEL EXPERIENCES'}</div><h3 style="color:white">${t('discover')}</h3></div></div></div><h2 class="gtitle">${t('roominfo')}</h2>${state.guest?.room_type?`<div class="guest-room-feature">${img(state.guest.room_type.image)}<div><div class="eyebrow">${state.lang==='he'?'החדר שלכם':'YOUR ROOM'}</div><h3>${esc(pick(state.guest.room_type,'name'))} · ${t('room')} ${esc(state.guest.stay.room)}</h3><p>${esc(pick(state.guest.room_type,'description'))}</p></div></div>`:''}<div class="guestgrid">${types.slice(0,3).map(r=>`<div class="gtile">${img(r.image)}<div class="inside"><h3>${esc(pick(r,'name'))}</h3><p>${esc(pick(r,'description'))}</p><span class="chip">${esc(r.size||'')} · ${r.max_guests} ${state.lang==='he'?'אורחים':'guests'}</span></div></div>`).join('')||empty()}</div><h2 class="gtitle">${t('services')}</h2><div class="guestgrid">${svc.map(s=>`<div class="gtile">${img(s.image)}<div class="inside"><h3>${esc(pick(s,'name'))}</h3><p>${esc(pick(s,'description'))}</p><span class="tag">${state.lang==='he'?({'spa':'ספא','dining':'מסעדה','facilities':'מתקנים','info':'מידע'}[s.category]||esc(s.category)):esc(s.category)}</span></div></div>`).join('')||empty()}</div><button class="btn full" data-action="install" style="margin-top:25px">⬇ &nbsp; ${t('addhome')}</button>`;}
function productCard(p){const count=state.cart[p.id]||0;return `<div class="productcard">${img(p.image)}<div class="desc"><h4>${esc(pick(p,'name'))}</h4><p>${esc(pick(p,'description'))}</p><div class="row"><strong>${fmt(p.price_cents,state.hotel.currency)}</strong><div class="qty"><button data-action="quantity" data-id="${p.id}" data-step="-1" aria-label="Remove one">−</button><strong data-product-count="${p.id}">${count}</strong><button data-action="quantity" data-id="${p.id}" data-step="1" aria-label="Add one">+</button></div></div></div></div>`;}
function updateCartUI(){
 const items=state.catalog.menu||[];
 const total=items.reduce((sum,p)=>sum+(state.cart[p.id]||0)*p.price_cents,0);
 const qty=Object.values(state.cart).reduce((sum,v)=>sum+v,0);
 document.querySelectorAll('[data-product-count]').forEach(n=>{n.textContent=state.cart[n.dataset.productCount]||0;});
 const count=document.getElementById('cartQty');
 const price=document.getElementById('cartTotal');
 const button=document.querySelector('#guestOrderForm button[type="submit"]');
 if(count)count.textContent=qty+' '+(state.lang==='he'?'פריטים':'items');
 if(price)price.textContent=fmt(total,state.hotel.currency);
 if(button){button.disabled=!guestAllowed('orders')||total<=0;button.textContent=t('checkout')+' · '+fmt(total,state.hotel.currency);}
}
function updateDeliveryDetail(){
 const area=document.getElementById('deliveryArea');
 const detail=document.querySelector('#guestOrderForm input[name="detail"]');
 if(!area||!detail)return;
 const needsDetail=area.value!=='room';
 detail.required=needsDetail;
 detail.minLength=needsDetail?2:0;
 detail.placeholder=needsDetail?(state.lang==='he'?'למשל: מיטת שיזוף 12 או שולחן 4':'e.g. Sunbed 12 or Table 4'):'';
 const info=document.getElementById('deliveryHint');
 if(info)info.textContent=needsDetail?(state.lang==='he'?'חובה לציין מיקום מדויק כדי שהצוות יוכל למצוא אותך.':'Please specify where the staff should deliver.'):(state.lang==='he'?'ההזמנה תימסר לחדר הרשום על השהייה.':'Delivered to the room on your guest pass.');
}
function guestDining(){const products=state.catalog.menu||[],types=[['drinks',state.lang==='he'?'משקאות':'Drinks'],['food',state.lang==='he'?'אוכל':'Food'],['snacks',state.lang==='he'?'נשנושים':'Snacks'],['desserts',state.lang==='he'?'קינוחים':'Desserts']];const total=products.reduce((a,p)=>a+(state.cart[p.id]||0)*p.price_cents,0);return `<div class="eyebrow">${state.lang==='he'?'מסעדה ובר המלון':'IN-RESORT DINING'}</div><h2 class="gtitle">${state.lang==='he'?'אוכל ושתייה':t('dining')+' & Drinks'}</h2><p class="subtitle">${state.lang==='he'?'אפשר להזמין ישירות לחדר, לבריכה, ללובי או לגינה. התשלום יירשם בחשבון החדר.':'Order to your room, pool, lobby or garden. Charges are added to your room folio.'}</p>${types.filter(([k])=>products.some(p=>p.category===k)).map(([cat,name])=>`<h3 class="gtitle">${name}</h3>${products.filter(p=>p.category===cat).map(productCard).join('')}`).join('')}${products.filter(p=>!types.some(([k])=>k===p.category)).map(productCard).join('')}<div class="panel section-gap"><div class="eyebrow">${state.lang==='he'?'ההזמנה שלכם':'YOUR CART'}</div><h3>${t('cart')}</h3><div class="itemrow"><strong id="cartQty">${Object.values(state.cart).reduce((a,b)=>a+b,0)} ${state.lang==='he'?'פריטים':'items'}</strong><strong id="cartTotal">${fmt(total,state.hotel.currency)}</strong></div><form id="guestOrderForm"><div class="formgrid" style="margin-top:17px"><div class="inputgroup"><label>${t('locations')}</label><select name="area" id="deliveryArea"><option value="room">${state.lang==='he'?'החדר שלי':'My room'}</option><option value="pool">${state.lang==='he'?'בריכה':'Pool'}</option><option value="lobby">${state.lang==='he'?'לובי':'Lobby'}</option><option value="beach">${state.lang==='he'?'חוף':'Beach'}</option><option value="restaurant">${state.lang==='he'?'מסעדה':'Restaurant'}</option><option value="garden">${state.lang==='he'?'גינה':'Garden'}</option></select></div><div class="inputgroup"><label>${state.lang==='he'?'מיקום מדויק (למשל כיסא 12)':'Precise location (e.g. Sunbed 12)'}</label><input name="detail" maxlength="90"><small id="deliveryHint" class="muted">${state.lang==='he'?'ההזמנה תימסר לחדר הרשום על השהייה.':'Delivered to the room on your guest pass.'}</small></div><div class="inputgroup wide"><label>${state.lang==='he'?'הערות להזמנה':'Special notes'}</label><input name="note" maxlength="300"></div></div><button class="btn primary full" type="submit" ${!guestAllowed('orders')||!total?'disabled':''} style="margin-top:18px">${t('checkout')} · ${fmt(total,state.hotel.currency)}</button></form>${!guestAllowed('orders')?`<div class="notice info">${state.guest?(state.lang==='he'?'הזמנת אוכל אינה פעילה עבור גישה זו. פנו לקבלה.':'Dining is not enabled for this guest pass. Please contact reception.'):(state.lang==='he'?'לשליחת הזמנות יש לפתוח גישת אורח דרך QR מהקבלה.':'Open an active guest QR pass to place orders.')}</div>`:''}<p class="mini muted" style="margin-top:12px">${state.lang==='he'?'חיוב יירשם לבדיקת הקבלה, לא תבוצע סליקת אשראי באתר.':'No online payment. The hotel confirms any payment externally.'}</p></div>`;}
function guestAmenities(){let rows=state.catalog.amenities||[];return `<div class="eyebrow">${state.lang==='he'?'נוחות האורחים':'GUEST COMFORT'}</div><h2 class="gtitle">${t('roomservice')}</h2><p class="subtitle">${state.lang==='he'?'חסר לכם משהו? שלחו בקשה והצוות יקבל אותה בקבלה.':'Need something? Send a request directly to the hotel team.'}</p><div class="section-gap">${rows.map(r=>`<div class="productcard">${img(r.image)}<div class="desc"><h4>${esc(pick(r,'name'))}</h4><p>${r.quota} ${state.lang==='he'?(r.basis==='guest'?'לכל אורח':'לחדר'):(r.basis==='guest'?'per guest':'per room')} / ${state.lang==='he'?(r.period==='daily'?'ביום':'לשהייה'):r.period}</p><div class="row"><span class="chip">${state.lang==='he'?'כלול בשירות':'Guest amenity'}</span><button class="btn primary small" data-action="guestRequest" data-id="${r.id}" ${!guestAllowed('requests')?'disabled':''}>${t('request')}</button></div></div></div>`).join('')||empty()}</div>`;}
function guestActivities(){let d=state.catalog.activities||[];return `<div class="eyebrow">${state.lang==='he'?'פעילויות וחוויות':'CURATED EXPERIENCES'}</div><h2 class="gtitle">${t('activities')}</h2><p class="subtitle">${state.lang==='he'?'הרשמה לפעילויות של המלון, עם מועדים ומספר מקומות מוגבל.':'Discover experiences and reserve your place.'}</p><div class="cards section-gap">${d.map(a=>`<div class="gtile">${img(a.image)}<div class="inside"><h3>${esc(pick(a,'name'))}</h3><p>${esc(pick(a,'description'))}</p><div style="margin-top:10px"><span class="chip">📍 ${esc(a.location)}</span> <span class="chip">${dateFmt(a.starts)}</span></div><div class="itemrow"><strong>${a.price_cents?fmt(a.price_cents,state.hotel.currency):state.lang==='he'?'ללא עלות':'Complimentary'}</strong><button class="btn primary small" data-action="guestBook" data-id="${a.id}" ${!guestAllowed('activities')?'disabled':''}>${t('book')}</button></div></div></div>`).join('')||empty()}</div>`;}
function guestChatShell(){return `<div class="eyebrow">${state.lang==='he'?'הקבלה לשירותכם':'AT YOUR SERVICE'}</div><h2 class="gtitle">${t('chatreception')}</h2><div id="guestMessages"><div class="panel">${state.guest?'Loading messages...':t('preview')}</div></div><form id="guestChatForm" class="messagebar"><input required name="body" placeholder="${state.lang==='he'?'כתבו הודעה לקבלה...':'Type a message to reception...'}" maxlength="1500" ${guestAllowed('chat')?'':'disabled'}><button class="btn primary" type="submit" ${guestAllowed('chat')?'':'disabled'}>➤</button></form>`;}
async function loadGuestChat(){if(!state.guest)return;let msgs=await api(hroute(state.slug,'guest/'+encodeURIComponent(state.token)+'/chat'));let node=document.getElementById('guestMessages');if(node){node.innerHTML=`<div class="chatbox">${msgs.map(m=>`<div class="bubble ${m.sender==='guest'?'mine':''}">${esc(m.body)}<div class="mini muted">${dateFmt(m.created)}</div></div>`).join('')||`<div class="muted">${state.lang==='he'?'תחילת השיחה שלך עם הקבלה':'Your conversation with reception starts here.'}</div>`}</div>`;node.querySelector('.chatbox').scrollTop=99999;}}
function guestMyShell(){return `<div class="eyebrow">${state.lang==='he'?'פרטי השהייה':'YOUR STAY'}</div><h2 class="gtitle">${t('my')}</h2><div id="guestMy"><div class="panel">${state.guest?'Loading...':t('preview')}</div></div>`;}
async function loadGuestMy(){let d=await api(hroute(state.slug,'guest/'+encodeURIComponent(state.token)+'/my'));let el=document.getElementById('guestMy');if(!el)return;let due=d.folio.filter(f=>f.status==='open').reduce((x,f)=>x+f.amount_cents,0);const confirmed=state.lastOrderConfirmation;el.innerHTML=`${confirmed?`<div class="notice info" style="margin-bottom:14px"><strong>✓ ${state.lang==='he'?'הזמנה מספר':'Order #'}${confirmed.id} ${state.lang==='he'?'נקלטה בקבלה':'received by reception'}</strong><div>📍 ${esc(deliveryLabel(confirmed.area,confirmed.room,state.lang))} ${confirmed.detail?' · '+esc(confirmed.detail):''}</div><div>${fmt(confirmed.total,state.hotel.currency)}</div></div>`:''}`+`<div class="panel"><div class="eyebrow">${state.lang==='he'?'חשבון החדר':'ROOM FOLIO'}</div><h3 style="margin:12px 0">${t('balance')}</h3><h2>${fmt(due,state.hotel.currency)}</h2><p class="mini muted" style="margin-top:8px">${state.lang==='he'?'הקבלה תאשר תשלום בצ׳ק־אאוט':'Settle at the reception desk on checkout.'}</p>${d.folio.map(f=>`<div class="itemrow"><span>${esc(f.description)}<br><small>${state.lang==='he'?({'open':'פתוח','paid':'שולם','void':'בוטל'}[f.status]||esc(f.status)):esc(f.status)}</small></span><strong>${fmt(f.amount_cents,state.hotel.currency)}</strong></div>`).join('')||'<p class="subtitle">No charges yet</p>'}</div><div class="panel section-gap"><h3>${t('requests')}</h3>${d.requests.map(r=>`<div class="itemrow"><span>${esc(pick(r,'name'))} × ${r.qty}</span><span class="chip">${esc(r.status)}</span></div>`).join('')||empty()}</div><div class="panel section-gap"><h3>${t('dining')} / ${t('activities')}</h3>${d.orders.map(o=>`<div class="itemrow"><span><strong>#${o.id} · 📍 ${esc(deliveryLabel(o.area,state.guest?.stay?.room,state.lang))}${o.detail?' · '+esc(o.detail):''}</strong><br><small>${esc(o.status)}${o.note?' · '+esc(o.note):''}</small></span><strong>${fmt(o.total_cents,state.hotel.currency)}</strong></div>`).join('')}${d.bookings.map(b=>`<div class="itemrow"><span>${esc(pick(b,'name'))} × ${b.qty}</span><button class="btn small" data-action="cancelBooking" data-id="${b.id}">${state.lang==='he'?'ביטול':'Cancel'}</button></div>`).join('')||empty()}</div>`;}
async function installApp(){if(state.prompt){try{state.prompt.prompt();await state.prompt.userChoice;state.prompt=null;return;}catch{}}
 const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent);let txt=ios?(state.lang==='he'?'<ol><li>פתחו את הקישור באמצעות Safari.</li><li>לחצו על כפתור השיתוף (ריבוע עם חץ למעלה).</li><li>בחרו ״הוסף למסך הבית״ ואשרו.</li></ol>':'<ol><li>Open this page in Safari.</li><li>Tap Share (square with arrow up).</li><li>Choose Add to Home Screen, then Add.</li></ol>'):(state.lang==='he'?'<ol><li>פתחו את האתר ב־Chrome.</li><li>לחצו על תפריט ⋮ בדפדפן.</li><li>בחרו ״הוספה למסך הבית״ או ״התקנת האפליקציה״.</li></ol>':'<ol><li>Open the page in Chrome.</li><li>Open the ⋮ menu.</li><li>Select Install app or Add to Home screen.</li></ol>');modal(`<div class="heading"><h2>${t('addhome')}</h2><button class="btn ghost" data-action="closeModal">✕</button></div><div class="installhelp">${txt}<p class="muted">${state.lang==='he'?'באייפון האתר אינו יכול להתקין את עצמו בלחיצה אחת. זאת מגבלה של Safari.':'On iOS, Safari requires manual installation. Websites cannot bypass this.'}</p></div>`);}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.prompt=e;});

// ----- Event handlers -----
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el){if(e.target.matches('.modalwrap'))closeModal();return;}const act=el.dataset.action;try{
 if(act==='changePassword'){modal(`<div class="heading"><h2>Change your password</h2><button class="btn ghost" data-action="closeModal">✕</button></div><form id="changePasswordForm"><div class="formgrid"><div class="inputgroup wide"><label>Current password</label><input type="password" required name="current_password"></div><div class="inputgroup wide"><label>New password (12+ characters)</label><input type="password" required minlength="12" name="new_password"></div></div><div class="formfoot"><button class="btn primary" type="submit">Change password →</button></div></form>`);return;}
 if(act==='logout'){await api('/api/auth/logout','POST',{});location.href='/login';return;}
 if(act==='closeModal'){closeModal();return;}
 if(act==='backOwner'){state.slug='';state.hotel=null;await loadHotels();renderOwner();history.replaceState({},'', '/owner');return;}
 if(act==='toggleHotel'){if(!confirm(el.dataset.active==='1'?'Suspend this hotel and all its guest links?':'Reactivate this hotel?'))return;await api('/api/owner/hotels/'+el.dataset.id,'POST',{active:el.dataset.active!=='1'});await loadHotels();renderOwner();notify('Hotel status updated');return;}
 if(act==='alerts'){state.alertsEnabled=!state.alertsEnabled;if(state.alertsEnabled){
     try{const AC=window.AudioContext||window.webkitAudioContext;if(AC){state.audioContext=new AC();await state.audioContext.resume();}}catch{}
     try{if('Notification' in window&&Notification.permission==='default')await Notification.requestPermission();}catch{}
   }
   renderManager();notify(state.alertsEnabled?'Sound alerts enabled while this page is open':'Sound alerts disabled');return;}
 if(act==='closeZeroStay'){if(!confirm('Close this guest stay? No payment will be recorded.'))return;await hotelApi('checkout/close','POST',{stay_id:Number(el.dataset.id)});closeModal();notify('Guest stay closed with zero balance');await loadSection();return;}
 if(act==='reviewCheckout'){await reviewCheckout(Number(el.dataset.id));return;}
 if(act==='printCheckout'){window.print();return;}
 if(act==='demoGuest'){
   const result=await hotelApi('demo-pass','POST',{});
   modal(`<div class="heading"><h2>Guest demo — room ${esc(result.room)}</h2><button class="btn ghost" data-action="closeModal">✕</button></div><p class="subtitle">This is a real test pass for the fictional concept hotel. Orders and charges will be visible in your reception dashboard.</p><div class="formfoot"><a class="btn primary" href="${esc(result.url)}" target="_blank" rel="noopener">Open guest app ↗</a><button class="btn" data-action="closeModal">Close</button></div>`);
   return;
 }
 if(act==='showEvents'){
   // Opening the inbox does not acknowledge operational requests.
   const el=document.getElementById('receptionLive');
   if(el)el.textContent='🔔 Reception feed';
   const events=state.receptionEvents||[];
   modal(`<div class="heading"><h2>Reception — recent guest activity</h2><button data-action="closeModal" class="btn ghost">✕</button></div><p class="subtitle">Refreshes automatically while the manager page is open. Allow sound alerts with the button in the header.</p>${events.length?events.map(ev=>receptionEventHTML(ev,true)).join(''):empty('No guest activity yet')}`);
   return;
 }
 if(act==='openRoom'){state.roomQuery=el.dataset.room||'';closeModal();navTo('room_history');return;}
 if(act==='searchRoom'){state.roomQuery=document.getElementById('roomHistoryInput')?.value.trim()||'';await loadSection();return;}
 if(act==='assignEvent'){
   if(!(isOwner()||state.auth?.user?.role==='manager'))throw Error('Hotel manager required');
   const staff=await hotelApi('staff');
   const targetPermission=EVENT_PERM[el.dataset.type];
   const eligible=staff.filter(x=>x.active&&(x.role==='manager'||x.permissions.some(p=>p==='edit:'+targetPermission||p===targetPermission)));
   if(!eligible.length){notify('No staff with permission for this category. Add a team member first.',true);return;}
   const current=(state.receptionEvents||[]).find(x=>x.id===Number(el.dataset.id)&&x.type===el.dataset.type);
   modal(`<div class="heading"><div><div class="eyebrow">FRONT DESK · ASSIGNMENT</div><h2>Assign Room ${esc(current?.room||'')}</h2></div><button class="btn ghost" data-action="closeModal">✕</button></div>
   <p class="subtitle">Choose a staff member who has permission to handle this category.</p>
   <form id="assignEventForm" data-type="${esc(el.dataset.type)}" data-id="${Number(el.dataset.id)}"><div class="inputgroup"><label>Assign to</label><select name="assignee_id">${eligible.map(st=>`<option value="${st.id}" ${current?.assigned_to===st.id?'selected':''}>${esc(st.display_name)} · ${esc(st.role)}</option>`).join('')}</select></div>
   <div class="formfoot"><button class="btn" type="button" data-action="closeModal">Cancel</button><button class="btn primary" type="submit">Assign employee</button></div></form>`);
   return;
 }
 if(act==='acceptEvent'||act==='claimEvent'){
   if(!canEdit(EVENT_PERM[el.dataset.type]))throw Error('You need editing permission to handle this item');
   el.disabled=true;
   try{await hotelApi('events/action','POST',{type:el.dataset.type,id:Number(el.dataset.id),action:act==='acceptEvent'?'acknowledge':'claim'});
     state.receptionEvents=await hotelApi('events');refreshLiveBoard();notify(act==='acceptEvent'?'Received and recorded for the team':'Assigned to your account');
   }catch(err){el.disabled=false;throw err;}
   return;
 }
 if(act==='markEventsRead'){recordEventRead();notify('Reception alerts marked as seen on this device');return;}
 if(act==='chooseImage'){let target=el.dataset.target,value=el.dataset.value;const selector=document.querySelector('select[name="'+target+'"]');if(selector){selector.value=value;selector.dispatchEvent(new Event('change',{bubbles:true}));}document.querySelectorAll('.photo-choice[data-target="'+target+'"]').forEach(b=>{b.classList.toggle('selected',b.dataset.value===value);let badge=b.querySelector('span');if(badge)badge.textContent=b.dataset.value===value?'✓ Current':'Select';});return;}
 if(act==='openEvent'){closeModal();navTo(el.dataset.tab);return;}
 if(act==='newHotel'){modal(`<div class="heading"><div><div class="eyebrow">PLATFORM OWNER</div><h2>Create a hotel</h2></div><button class="btn ghost" data-action="closeModal">✕</button></div><form id="newHotelForm"><div class="formgrid"><div class="inputgroup"><label>Hotel name</label><input name="name" required placeholder="Palm Bay Retreat"></div><div class="inputgroup"><label>URL slug</label><input name="slug" required pattern="[a-z][a-z0-9-]{2,39}" placeholder="palm-bay"></div><div class="inputgroup"><label>Location</label><input name="location" placeholder="Thailand"></div><div class="inputgroup"><label>Currency</label><select name="currency"><option>USD</option><option>ILS</option><option>LKR</option><option>THB</option><option>EUR</option></select></div><div class="inputgroup"><label>Language</label><select name="language"><option value="en">English</option><option value="he">עברית</option></select></div></div><div class="notice info">After creation open its workspace, create a manager under Team & Access, and upload this hotel's own photographs.</div><div class="formfoot"><button class="btn primary" type="submit">Create hotel →</button></div></form>`);return;}
 if(act==='openHotel'){state.slug=el.dataset.slug;state.lastEventIds=null;state.receptionSeen=null;state.roomQuery="";state.roomFilter="";state.assets=[];await loadHotelManagement();state.tab='dashboard';history.replaceState({},'', '/manager?hotel='+encodeURIComponent(state.slug));renderManager();return;}
 if(act==='tab'){navTo(el.dataset.tab);return;}
 if(act==='gotab:rooms'||act==='gotab:media'){navTo(act.split(':')[1]);return;}
 if(act==='refresh'){loadSection().then(()=>state.tab==='chat'&&loadChatThread());return;}
 if(act==='newItem'){if(!canEdit(el.dataset.resource==='room_types'?'rooms':el.dataset.resource))throw Error('View-only access');await formResource(el.dataset.resource);return;}
 if(act==='editItem'){if(!canEdit(el.dataset.resource==='room_types'?'rooms':el.dataset.resource))throw Error('View-only access');await formResource(el.dataset.resource,+el.dataset.id);return;}
 if(act==='archiveItem'){if(!canEdit(el.dataset.resource==='room_types'?'rooms':el.dataset.resource))throw Error('View-only access');if(!confirm('Archive this item? Existing guest order history is preserved.'))return;await hotelApi(el.dataset.resource+'/'+el.dataset.id,'DELETE');notify('Item archived');await loadSection();return;}
 if(act==='newStay'){await stayModal();return;}
 if(act==='showQr'){let s=(await hotelApi('stays')).find(x=>x.id==el.dataset.id);if(s)showPass(s);return;}
 if(act==='revokeStay'){if(!confirm('Revoke this room access immediately?'))return;await hotelApi('stays/'+el.dataset.id,'PUT',{});notify('Access revoked');loadSection();return;}
 if(act==='newStaff'){staffModal();return;}
 if(act==='editStaff'){staffModal(+el.dataset.id);return;}
 if(act==='selectThread'){state.selectedThread=+el.dataset.id;await loadSection();await loadChatThread();return;}
 if(act==='copy'){await navigator.clipboard.writeText(el.dataset.value||'');notify('Copied');return;}
 if(act==='guestTab'){state.guestTab=el.dataset.tab;renderGuest();window.scrollTo({top:0,behavior:'instant'});return;}
 if(act==='install'){await installApp();return;}
 if(act==='quantity'){let id=el.dataset.id;state.cart[id]=Math.max(0,Math.min(12,(state.cart[id]||0)+Number(el.dataset.step)));updateCartUI();return;}
 if(act==='guestRequest'){if(!state.guest)return;let id=+el.dataset.id;let a=state.catalog.amenities.find(a=>a.id===id);modal(`<div class="heading"><h2>${esc(pick(a,'name'))}</h2><button data-action="closeModal" class="btn ghost">✕</button></div><form id="guestRequestForm" data-id="${id}"><p class="subtitle">${t('request')} · ${a.quota} ${a.basis} / ${a.period}</p><div class="inputgroup" style="margin-top:15px"><label>${state.lang==='he'?'כמות':'Quantity'}</label><input name="qty" type="number" min="1" max="20" value="1"></div><div class="formfoot"><button class="btn primary" type="submit">${t('request')}</button></div></form>`);return;}
 if(act==='cancelBooking'){if(!state.guest)return;if(!confirm(state.lang==='he'?'לבטל את ההרשמה?':'Cancel this activity booking?'))return;await api(hroute(state.slug,'guest/'+state.token+'/cancel_booking'),'POST',{booking_id:Number(el.dataset.id)});await loadGuestMy();notify('Booking cancelled');return;}
 if(act==='guestBook'){if(!state.guest)return;let id=+el.dataset.id,a=state.catalog.activities.find(a=>a.id===id);modal(`<div class="heading"><h2>${esc(pick(a,'name'))}</h2><button data-action="closeModal" class="btn ghost">✕</button></div><form id="guestBookForm" data-id="${id}"><p class="subtitle">${dateFmt(a.starts)} · ${fmt(a.price_cents,state.hotel.currency)} per guest</p><div class="inputgroup" style="margin-top:15px"><label>${state.lang==='he'?'משתתפים':'Participants'}</label><input type="number" name="qty" min="1" max="${state.guest.stay.guests}" value="1"></div><div class="formfoot"><button class="btn primary" type="submit">${t('book')}</button></div></form>`);return;}
 }catch(err){renderError(err);}});

document.addEventListener('input',e=>{if(e.target.id==='roomFilter'){state.roomFilter=e.target.value;applyRoomFilter();} });
document.addEventListener('keydown',e=>{if(e.target.id==='roomHistoryInput'&&e.key==='Enter'){e.preventDefault();state.roomQuery=e.target.value.trim();loadSection().catch(renderError);}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='deliveryArea'){updateDeliveryDetail();return;}
 if(el.id==='langPicker'){state.lang=el.value;localStorage.setItem('stayos_lang',el.value);renderGuest();return;}
 if(el.dataset.status){await hotelApi(el.dataset.status+'/status','POST',{id:+el.dataset.id,status:el.value});notify('Status updated');await loadSection();return;}
 if(el.matches('select[name="image"],select[name="hero_image"],select[name="logo_image"]')){const p=document.querySelector('[data-preview-for="'+el.name+'"]');if(p)p.src=pathImg(el.value);return;}
 if(el.dataset.imageUpload){if(!canEdit('media'))throw Error('Photo uploads require Media Library edit permission');const files=Array.from(el.files||[]);if(!files.length)return;if(files.length>12)throw Error('Upload a maximum of 12 photos at a time');for(let file of files){if(file.size>7*1024*1024)throw Error('Image exceeds 7 MB');let data=await hotelApi('media','POST',file,true);if(el.dataset.imageUpload==='gallery'){state.assets.unshift(data.url);}else{let name=el.dataset.imageUpload==='1'?'image':el.dataset.imageUpload;let selector=document.querySelector(`select[name="${name}"]`);if(selector){selector.add(new Option('New uploaded photo',data.url,true,true));}let p=document.querySelector('[data-preview-for="'+name+'"]');if(p)p.src=data.url;const gallery=el.closest('.photo-editor')?.querySelector('.photo-choices');if(gallery){const node=document.createElement('button');node.type='button';node.className='photo-choice selected';node.dataset.action='chooseImage';node.dataset.target=name;node.dataset.value=data.url;node.innerHTML='<img src="'+esc(data.url)+'" alt="New upload"><span>✓ Current</span>';gallery.prepend(node);} }}notify('Photo uploaded');if(el.dataset.imageUpload==='gallery')loadSection();return;}
 }catch(err){renderError(err);}});

document.addEventListener('submit',async e=>{let form=e.target;if(!form.id)return;e.preventDefault();let data=Object.fromEntries(new FormData(form).entries());let submit=form.querySelector('button[type=submit]');if(submit)submit.disabled=true;try{
 if(form.id==='assignEventForm'){
   await hotelApi('events/action','POST',{type:form.dataset.type,id:Number(form.dataset.id),action:'assign',assignee_id:Number(data.assignee_id)});
   closeModal();state.receptionEvents=await hotelApi('events');refreshLiveBoard();notify('Assignment saved in reception log');return;
 }
 if(form.id==='changePasswordForm'){await api('/api/auth/change-password','POST',data);notify('Password changed. Please sign in again.');location.href='/login';return;}
 if(form.id==='loginForm'){await api('/api/auth/login','POST',data);state.auth=await api('/api/auth/me');if(state.auth.user.role==='owner'){await loadHotels();history.replaceState({},'','/owner');renderOwner();}else{const result=await api('/api/auth/myhotel');state.slug=result.slug;localStorage.setItem('stayos_hotel_slug',state.slug);await loadHotelManagement();state.tab='dashboard';history.replaceState({},'','/manager');renderManager();}notify('Welcome back');return;}
 if(form.id==='newHotelForm'){let result=await api('/api/owner/hotels','POST',data);closeModal();await loadHotels();renderOwner();notify('Hotel created: '+result.slug);return;}
 if(form.id==='resourceForm'){const res=form.dataset.resource,id=form.dataset.id;let b={};for(let k of FIELDS[res]){let val=data[k];if(k==='price_cents')b[k]=Math.round((Number(val)||0)*100);else if(['starts','ends'].includes(k))b[k]=new Date(val).toISOString();else if(['max_guests','capacity','quota','room_type_id','active'].includes(k))b[k]=Number(val);else b[k]=val??'';}
 await hotelApi(res+(id?'/'+id:''),id?'PUT':'POST',b);closeModal();notify(id?'Item updated':'New item added');await loadSection();return;}
 if(form.id==='brandingForm'){let b={...data};await hotelApi('branding','POST',b);await loadPublic();closeModal();notify('Branding saved');await loadSection();return;}
 if(form.id==='staffForm'){let id=form.dataset.id,perms=[...form.querySelectorAll('select[data-perm]')].filter(i=>i.value!=='none').map(i=>i.value+':'+i.dataset.perm);let b={...data,permissions:perms};if(id){b.active=Number(b.active||0);await hotelApi('staff/'+id,'PUT',b);}else{await hotelApi('staff','POST',b);}closeModal();state.staff=await hotelApi('staff');await loadSection();notify('Staff access saved');return;}
 if(form.id==='stayForm'){let b={...data,zones:[...form.querySelectorAll('input[name="zones"]:checked')].map(i=>i.value),guests:Number(data.guests),room_id:Number(data.room_id),start:new Date(data.start).toISOString(),ends:new Date(data.ends).toISOString()};let result=await hotelApi('stays','POST',b);closeModal();notify('New guest QR created');await loadSection();let stay=(await hotelApi('stays')).find(s=>s.id===result.id);if(stay)showPass(stay);return;}
 if(form.id==='checkoutConfirmForm'){if(data.collected!=='yes')throw Error('Confirm collection at the hotel desk first');if(!confirm('The hotel has ALREADY collected '+fmt(Number(form.dataset.amount),state.hotel.currency)+' using its own payment method. Record this and close the guest pass?'))return;let r=await hotelApi('folio/settle','POST',{stay_id:Number(form.dataset.stay),expected_amount_cents:Number(form.dataset.amount),method:data.method,reference:data.reference||''});closeModal();notify('Recorded external collection: '+fmt(r.amount_cents,state.hotel.currency));await loadSection();return;}
 if(form.id==='staffChatForm'){await hotelApi('chat','POST',{stay_id:state.selectedThread,body:data.body});form.reset();await loadChatThread();return;}
 if(form.id==='guestRequestForm'){await api(hroute(state.slug,'guest/'+state.token+'/request'),'POST',{amenity_id:Number(form.dataset.id),qty:Number(data.qty)});closeModal();notify(t('sent'));return;}
 if(form.id==='guestBookForm'){await api(hroute(state.slug,'guest/'+state.token+'/book'),'POST',{activity_id:Number(form.dataset.id),qty:Number(data.qty)});closeModal();notify(t('sent'));return;}
 if(form.id==='guestOrderForm'){let items=Object.entries(state.cart).filter(([,qty])=>qty>0).map(([id,qty])=>({product_id:Number(id),qty}));if(!items.length)throw Error('Choose at least one item');if(data.area!=='room'&&String(data.detail||'').trim().length<2)throw Error(state.lang==='he'?'צריך לציין מקום מדויק למשל מיטת שיזוף 12':'Enter a precise delivery location');if(!state.pendingOrderKey)state.pendingOrderKey=Array.from(crypto.getRandomValues(new Uint8Array(20)),v=>v.toString(16).padStart(2,'0')).join('');let result=await api(hroute(state.slug,'guest/'+state.token+'/order'),'POST',{items,area:data.area,detail:data.detail||'',note:data.note||'',request_key:state.pendingOrderKey});state.pendingOrderKey=null;state.cart={};state.lastOrderConfirmation={id:result.id,area:data.area,detail:data.detail||'',note:data.note||'',room:state.guest?.stay?.room,total:result.total_cents};state.guestTab='my';renderGuest();notify(t('sent')+' · '+deliveryLabel(data.area,state.guest?.stay?.room,state.lang)+(data.detail?' · '+data.detail:''));return;}
 if(form.id==='guestChatForm'){await api(hroute(state.slug,'guest/'+state.token+'/chat'),'POST',{body:data.body});form.reset();await loadGuestChat();return;}
 }catch(err){renderError(err);}finally{if(submit)submit.disabled=false;}});

// Single app shell. Avoid offline caching of room tokens or authenticated data.
state.lang=localStorage.getItem('stayos_lang')||'he';
if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){
 navigator.serviceWorker.register('/sw.js').catch(()=>{});
}
function playAlert(){if(!state.audioContext)return;try{let ctx=state.audioContext,o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(760,ctx.currentTime);g.gain.setValueAtTime(.03,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.24);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.25);}catch{}}
async function checkAlerts(){
 if(state.alertPollBusy)return;
 state.alertPollBusy=true;
 try{
  if(state.guest){
   if(!state.token)return;
   const replies=await api(hroute(state.slug,'guest/'+encodeURIComponent(state.token)+'/chat'));
   const latest=Math.max(0,...replies.filter(m=>m.sender==='reception').map(m=>Number(m.id)||0));
   if(state.lastGuestReplyId!==null&&latest>state.lastGuestReplyId)notify(state.lang==='he'?'התקבלה הודעה חדשה מהקבלה':'New message from reception');
   state.lastGuestReplyId=latest;
   if(state.guestTab==='chat')await loadGuestChat();return;
  }
  if(!state.auth?.authenticated||!state.slug)return;
  const events=await hotelApi('events');state.receptionEvents=events;state.lastAlertSuccess=Date.now();state.lastAlertFailure=0;
  const newest={};for(const event of events)newest[event.type]=Math.max(newest[event.type]||0,event.id);
  const seenKey='stayos_seen_'+state.slug+'_'+state.auth.user.id;
  if(state.receptionSeen===null){let saved;try{saved=JSON.parse(localStorage.getItem(seenKey)||'null');}catch{}state.receptionSeen=saved&&typeof saved==='object'?saved:newest;
    if(!saved)try{localStorage.setItem(seenKey,JSON.stringify(newest));}catch{}
  }
  state.unreadEvents=events.filter(event=>event.action_needed&&!event.acknowledged_at).length;
  if(state.lastEventIds!==null){
    const arrivals=events.filter(e=>e.id>(state.lastEventIds[e.type]||0));
    if(arrivals.length){for(const event of arrivals.slice(0,3).reverse())receptionPopup(event);
      if(state.alertsEnabled){playAlert();try{if('Notification' in window&&Notification.permission==='granted'){let e=arrivals[0];new Notification('STAYOS · '+kindUI(e.type)[1],{body:'Room '+e.room+' · '+e.label,tag:'stayos-'+state.slug+'-'+e.type+'-'+e.id});}}catch{}}
    }
  }
  state.lastEventIds=newest;
  const button=document.getElementById('receptionLive');if(button)button.textContent='🔔 Reception feed'+(state.unreadEvents?' ('+state.unreadEvents+' pending)':'');
  refreshLiveBoard();
  if(['requests','orders','chat','bookings'].includes(state.tab)&&!state.modal){await loadSection();applyRoomFilter();}
 }catch(err){
   state.lastAlertFailure++;
   if(state.lastAlertFailure===4){notify('Reception connection interrupted. Check internet and Railway.',true);}
   const status=document.getElementById('receptionConnection');if(status)status.outerHTML=eventHealthStatus();
 }
 finally{state.alertPollBusy=false;}
}
window.setInterval(checkAlerts,4000);
init();